        public static string Get(K key, string language)
        {
            var lang = InngameTranslation.BaseLang(language);
            if (lang == "no" || lang == "nn") lang = "nb"; // Norwegian: the table uses Bokmål
            if (!table.TryGetValue(lang, out var arr)) arr = table["en"];
            int i = (int)key;
            return i < arr.Length ? arr[i] : table["en"][i];
        }

        public static IEnumerable<string> Languages => table.Keys;
        internal static int Count(string lang) => table.TryGetValue(lang, out var a) ? a.Length : 0;
    }
